xfs_buf_t*
xfs_buf_find(struct xfs_buftarg *btp, struct xfs_buf_map *map, int nmaps,
             xfs_buf_flags_t flags, xfs_buf_t *new_bp)
{
    xfs_buf_t *bp;
    int i;
    xfs_daddr_t daddr;
    int nblocks;
    int aligned;

    nblocks = 0;
    aligned = 1;
    for (i = 0; i < nmaps; i++) {
        nblocks += map[i].bm_len;
        if ((map[i].bm_offset & (btp->bt_blocksize - 1)) != 0)
            aligned = 0;
    }

    if (!aligned)
        return NULL;

    daddr = map[0].bm_offset;
    if (xfs_daddr_to_bno(btp, daddr) >= XFS_FSB_TO_DADDR(btp, btp->bt_partmap->pm_max_alloc))
        return NULL;

    bp = xfs_buf_find(btp, daddr, nblocks, flags);
    if (bp) {
        if (xfs_buf_isstale(bp)) {
            xfs_buf_stale(bp);
            xfs_buf_relse(bp);
            return NULL;
        }
        if (xfs_buf_lock(bp, flags))
            return NULL;
        return bp;
    }

    if (new_bp) {
        if (xfs_buf_init(new_bp, btp, nblocks, flags)) {
            xfs_buf_insert(new_bp, btp, daddr);
            xfs_buf_hold(new_bp);
            return new_bp;
        }
        xfs_buf_free(new_bp);
    }

    return NULL;
}

xfs_buf_t*
xfs_buf_search(struct xfs_buftarg *btp, struct xfs_buf_map *map, int nmaps,
		xfs_buf_flags_t flags, xfs_buf_t *new_bp)
{
	xfs_buf_t	*bp;
	xfs_daddr_t	blkno;
	uint		numblks;
	uint		i;
	int		error;

	blkno = map->bm_bn;
	numblks = 0;
	for (i = 0; i < nmaps; i++) {
		numblks += XFS_BUF_MAP_SIZE(&map[i]);
	}

	/*
	 * Check for proper alignment.
	 */
	if (blkno != XFS_DADDR_NULL && (blkno & (btp->bt_sshift - 1))) {
		return NULL;
	}

	/*
	 * Check that the block number is within valid bounds.
	 */
	if (blkno >= btp->bt_part_map[XFS_DADDR_METADATA] &&
	    blkno < XFS_DADDR_NULL)
		return NULL;

	/*
	 * Search the buffer cache.
	 */
	bp = xfs_buf_find(btp, blkno, numblks, flags);
	if (bp) {
		/*
		 * Check if the buffer is stale.
		 */
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			return NULL;
		}
		/*
		 * Attempt to lock the buffer.
		 */
		if (xfs_buf_lock(bp)) {
			xfs_buf_relse(bp);
			return NULL;
		}
		return bp;
	}

	/*
	 * No existing buffer found. Insert a new one if provided.
	 */
	if (new_bp) {
		new_bp->b_bn = blkno;
		new_bp->b_bno = blkno;
		new_bp->b_bno = blkno;
		new_bp->b_flags = flags;
		new_bp->b_target = btp;
		new_bp->b_count = 1;
		new_bp->b_file = NULL;
		new_bp->b_offset = 0;
		new_bp->b_error = 0;
		new_bp->b_iodone = NULL;
		new_bp->b_iodone_private = NULL;
		new_bp->b_ops = NULL;
		new_bp->b_data = NULL;

		xfs_buf_insert(new_bp);
		return new_bp;
	}

	return NULL;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp = NULL;
	uint64_t		total_bytes = 0;
	uint64_t		i;

	for (i = 0; i < nmaps; i++) {
		total_bytes += map[i].bm_len;
	}

	if (!xfs_buf_validate_alignment(btp, map[0].bm_offset, total_bytes))
		return NULL;

	if (map[0].bm_offset + (total_bytes >> btp->bt_sshift) > btp->bt_part_map.bm_len)
		return NULL;

	bp = xfs_buf_find_common(btp, map, nmaps, flags);

	if (bp) {
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
		}
		if (xfs_buf_lock(bp)) {
			return NULL;
		}
		return bp;
	}

	if (new_bp) {
		new_bp->b_flags |= flags;
		xfs_buf_insert(new_bp, btp);
		xfs_buf_hold(new_bp);
		return new_bp;
	}

	return NULL;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_daddr_t		bno;
	size_t			numblks;
	size_t			i;
	xfs_buf_t		*bp;
	xfs_buf_t		*newbuf = NULL;
	uint			locker = 0;

	numblks = 0;
	for (i = 0; i < nmaps; i++) {
		numblks += XFS_BUF_MAP_SIZE(&map[i]);
	}

	if ((numblks == 0) || (numblks > XFS_BB_TO_B(btp, XFS_MAX_FILESIZE)))
		return NULL;

	bno = XFS_BUF_MAP_START(map);
	if (bno >= XFS_FSB_TO_BB(btp, XFS_MAX_FILESIZE))
		return NULL;

	bp = xfs_buf_find_uncached(btp, bno, numblks, flags);
	if (bp)
		return bp;

	if (new_bp) {
		newbuf = new_bp;
	} else {
		newbuf = xfs_buf_alloc(btp, numblks, flags);
		if (!newbuf)
			return NULL;
	}

	xfs_buf_init(newbuf, bno, numblks, flags);
	xfs_buf_insert(newbuf, btp);

	return newbuf;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_mount	*mp = btp->bt_mount;
	xfs_daddr_t		bno = XFS_BUF_MAP_TO_BB(map);
	uint			bblks = XFS_BUF_MAP_BLK_CNT(map);
	xfs_buf_t		*bp;
	int			error;

	/*
	 * Check that the buffer is aligned to the device's logical sector size.
	 */
	if (XFS_BB_TO_FSBT(mp, bno) != XFS_BB_TO_FSBT(mp, bno + bblks - 1)) {
		ASSERT(0);
		return NULL;
	}

	if (bno + bblks < bno) {
		ASSERT(0);
		return NULL;
	}

	if (XFS_FSB_TO_AGNO(mp, XFS_BB_TO_FSB(mp, bno)) < 0 ||
	    XFS_FSB_TO_AGNO(mp, XFS_BB_TO_FSB(mp, bno + bblks - 1)) < 0) {
		ASSERT(0);
		return NULL;
	}

	/*
	 * Search for the buffer in the buffer cache.
	 */
	bp = xfs_buf_find_ag(btp, XFS_BUF_MAP_TO_FSB(map),
			     XFS_BUF_MAP_BLK_CNT(map), flags);
	if (bp) {
		if (xfs_buf_islocked(bp)) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			bp = NULL;
		}
	}

	if (!bp) {
		/*
		 * No buffer found, use the provided new buffer.
		 */
		bp = new_bp;
		error = xfs_buf_insert(btp, bp, flags);
		if (error) {
			return NULL;
		}
	}

	return bp;
}
